using System.Collections;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "RecoverAllHeartsReward", menuName = "Data/Rewards/RecoverAllHeartsReward", order = 0)]
public class RecoverAllHeartsReward : Reward
{
	[Header("Gain Heart Reward")]
	[SerializeField]
	private VoidEvent OnRecoverAllHearts;

	[Header("Recover Heart Particles Prefab")]
	[SerializeField]
	private GameObject recoverHeartParticlesPrefab;

	[Header("SFX")]
	[SerializeField]
	private GainHeartReward gainHeartReward;

	public override void GetReward()
	{
		ReferenceSingleton<CoroutineHandler>.Instance.Run(RecoverAllHeartsCoroutine());
	}

	private IEnumerator RecoverAllHeartsCoroutine()
	{
		yield return new WaitForSeconds(0.5f);
		ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
		OnRecoverAllHearts.Raise();
		ReferenceSingleton<VFXHandler>.Instance.GetVFX(recoverHeartParticlesPrefab, 3f);
		gainHeartReward.PlayGainHeartRewardSFX();
		yield return new WaitForSeconds(1.5f);
		ReferenceSingleton<GameStateManager>.Instance.SetEndOfBattleStateWithQueueLockFalse();
	}
}
